command:
if (!game.user.isGM) return ui.notifications.warn('Release Player Controls is GM-only.');

const api = game.emblemRpg.api;
const lock = api.movement.getLock();
if (!lock) return ui.notifications.info('No unit is under token control; nothing to release.');
if (lock.holderId === game.user.id) {
  return ui.notifications.warn(`You hold ${lock.tokenName} yourself — cancel your own plan instead.`);
}

const holder = game.users.get(lock.holderId);
const proceed = await foundry.applications.api.DialogV2.confirm({
  window: { title: 'Release Player Controls' },
  classes: ['emblem-rpg', 'dialog-editor'],
  content: `
    <div class="ed-container">
      <div class="ed-section ed-section--highlight">
        <p class="ed-description">${foundry.utils.escapeHTML(lock.holderName)} is pathfinding
          ${foundry.utils.escapeHTML(lock.tokenName)}.</p>
      </div>
      <div class="ed-section">
        <p class="ed-description">Cancel that plan, return the unit to where it started and release token
          control, exactly as the holder's own cancel key would. Token lockdown clears for the whole table.</p>
      </div>
    </div>`,
  rejectClose: false
});
if (!proceed) return;

const result = await api.recovery.clearLock({ announcement: 'timeout' });
console.log('emblem-rpg | Release Player Controls', { lock, holder: holder?.name ?? 'offline', result });
if (!result.ok) {
  ui.notifications.warn(`Token control was not released (${result.code}). Try again once the table is idle.`);
} else if (result.data?.cleared !== true) {
  ui.notifications.warn('Token control was already clear by the time the host answered.');
}
